<?php require __DIR__.'/../includes/auth.php';$pdo=db();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([user()['id']]);$u=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');if($first&&$last){$pdo->prepare('UPDATE users SET first_name=?,last_name=?,phone=?,address=? WHERE id=?')->execute([$first,$last,trim($_POST['phone']??''),trim($_POST['address']??''),$u['id']]);$_SESSION['user']['name']=$first.' '.$last;flash('success','Profile updated.');header('Location: profile.php');exit;}flash('error','First and last name are required.');}$pageTitle='My profile';require __DIR__.'/../includes/header.php';?><div class="panel"><h1>My profile</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><div><label>First name</label><input required name="first_name" value="<?=e($u['first_name'])?>"></div><div><label>Last name</label><input required name="last_name" value="<?=e($u['last_name'])?>"></div><div><label>Phone</label><input name="phone" value="<?=e($u['phone'])?>"></div><div><label>Email</label><input disabled value="<?=e($u['email'])?>"></div></div><label>Address</label><textarea name="address"><?=e($u['address'])?></textarea><p><button>Save profile</button></p></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
